  const touchX = useRef(0);
  const lastWheel = useRef(0);

  const go = (n) => { if (n >= 0 && n < TOTAL) setC(n); };

  useEffect(() => {
    const h = (e) => {
      if (e.key === "ArrowRight" || e.key === " ") { e.preventDefault(); go(c + 1); }
      if (e.key === "ArrowLeft") { e.preventDefault(); go(c - 1); }
    };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  });

  const onWheel = (e) => {
    const now = Date.now();
    if (now - lastWheel.current < 800) return;
    const d = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
    if (Math.abs(d) > 20) { lastWheel.current = now; go(c + (d > 0 ? 1 : -1)); }
  };

